@blog_bp.route('/api/blogs', methods=['GET'])
def get_blogs() -> Tuple[Dict, int]: ...

@blog_bp.route('/api/blogs/<int:blog_id>', methods=['GET'])
def get_blog(blog_id: int) -> Tuple[Dict, int]: ...

@blog_bp.route('/api/blogs/<int:blog_id>', methods=['PUT'])
def update_blog(blog_id: int) -> Tuple[Dict, int]: ...

@blog_bp.route('/api/blogs/<int:blog_id>', methods=['DELETE'])
def delete_blog(blog_id: int) -> Tuple[Dict, int]: ...

@blog_bp.route('/api/blogs/<int:blog_id>/images', methods=['POST'])
